import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
});

test('createInvoice normalizes customer ID', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const result = createInvoice({
    customerId: ' c-003 ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice finds customer with normalized ID', () => {
  const result = createInvoice({
    customerId: 'c-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  // Should succeed because c-002 normalizes to C-002 which exists
  assert.equal(result.value.customerId, 'C-002');
});

test('createInvoice sets default NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2024-02-14');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2024-01-29');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2024-02-14');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2024-01-31');
});

test('createInvoice calculates EOM for different months', () => {
  const feb = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(feb.value.dueDate, '2024-02-29'); // leap year

  const dec = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(dec.value.dueDate, '2024-12-31');
});

test('createInvoice rejects invalid terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'INVALID',
  });

  assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice preserves terms through operations', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
    terms: 'NET14',
  });

  const invoice = result.value;
  assert.equal(invoice.terms, 'NET14');
  assert.equal(invoice.dueDate, '2024-01-29');

  // Remove a line
  const removed = removeLine(invoice, 'DES-HOUR');
  assert.equal(removed.value.terms, 'NET14');
  assert.equal(removed.value.dueDate, '2024-01-29');

  // Issue the invoice
  const issued = issueInvoice(invoice, []);
  assert.equal(issued.value.terms, 'NET14');
  assert.equal(issued.value.dueDate, '2024-01-29');
});

test('createInvoice enriches lines with catalogue data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice fails with CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice fails with DATE_INVALID for bad date format', () => {
  const cases = [
    '2024-1-15',
    '2024/01/15',
    '01-15-2024',
    'invalid',
    '',
    '2024-13-01',
    '2024-02-30',
    '2024-00-01',
    '2024-01-00',
  ];

  for (const issueDate of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should fail for ${issueDate}`);
    assert.equal(result.error, 'DATE_INVALID', `Should fail with DATE_INVALID for ${issueDate}`);
  }
});

test('createInvoice fails with NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice fails with QTY_INVALID for invalid quantities', () => {
  const cases = [0, -1, -10, 1.5, 10.5, NaN, Infinity, null, undefined, '5'];

  for (const qty of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should fail for qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID', `Should fail with QTY_INVALID for qty ${qty}`);
  }
});

test('createInvoice fails with UNKNOWN_SKU for unknown product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-PRODUCT', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-20',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 16 },
      { sku: 'PRINT-A4', qty: 500 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[2].name, 'Printed flyer A4 (each)');
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 1 }];
  const originalLines = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 500, unitPrice: 37 }), 18500);
});

test('lineTotal works with qty 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('lineDiscount calculates discount on line total', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 10 }), 9500);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 0); // undefined = 0%
});

test('lineVAT calculates VAT on amount after discount', () => {
  // 10 × 9500 = 95000
  // No discount
  // 21% VAT = 19950
  const line1 = { qty: 10, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineVAT(line1), 19950);

  // 10 × 9500 = 95000, 10% discount = 9500
  // After discount: 85500
  // 21% VAT = 17955
  const line2 = { qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 };
  assert.equal(lineVAT(line2), 17955);

  // 0% VAT
  const line3 = { qty: 10, unitPrice: 9500, vatRate: 0 };
  assert.equal(lineVAT(line3), 0);
});

test('lineVAT with different VAT rates', () => {
  // 9% VAT
  const line9 = { qty: 100, unitPrice: 37, vatRate: 9 };
  assert.equal(lineVAT(line9), 333); // 3700 × 9% = 333

  // 21% VAT
  const line21 = { qty: 100, unitPrice: 980, vatRate: 21 };
  assert.equal(lineVAT(line21), 20580); // 98000 × 21% = 20580
});

test('invoiceTotals sums all line totals', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // 10 × 9500 + 5 × 8500 = 95000 + 42500 = 137500
  // 21% VAT = 28875
  // Total = 137500 + 28875 = 166375
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 28875);
  assert.equal(totals.total, 166375);
});

test('invoiceTotals includes VAT in total', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'ICON-SET', qty: 100 }],
  });

  const totals = invoiceTotals(result.value);
  // 100 × 980 = 98000
  // 21% VAT = 20580
  // Total = 118580 (not equal to subtotal)
  assert.equal(totals.subtotal, 98000);
  assert.equal(totals.vat, 20580);
  assert.equal(totals.total, 118580);
});

test('invoiceTotals with single line', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
  });

  const totals = invoiceTotals(result.value);
  // 2 × 245000 = 490000
  // 21% VAT = 102900
  // Total = 592900
  assert.equal(totals.subtotal, 490000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 102900);
  assert.equal(totals.total, 592900);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 100, discountPercent: 0 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
  assert.equal(result.value.lines[1].discountPercent, undefined);
});

test('createInvoice rejects invalid discountPercent', () => {
  const cases = [
    { sku: 'DEV-HOUR', qty: 1, discountPercent: -1 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 101 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 'invalid' },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: NaN },
  ];

  for (const line of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [line],
    });
    assert.equal(result.ok, false, `Should fail for discountPercent ${line.discountPercent}`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
});

test('createInvoice allows omitting discountPercent (applies tier discount)', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined); // standard = 0%
});

test('createInvoice accepts decimal discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice applies gold tier discount (5%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-001', // Northwind Studio, gold tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount (2.5%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2024-01-15',
