  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice explicit discount (0) overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
